---@type string
local config_dir = (debug.getinfo(1, "S").source:sub(2):match("(.+)/[^/]+$"))
  or "."

package.path = table.concat({
  config_dir .. "/lua/?.lua",
  config_dir .. "/lua/?/init.lua",
  package.path,
}, ";")

require("hyprconf").setup()

-- Apply the Hyprland theme generated by Noctalia.
require("noctalia").apply_theme()
